function saveData(){try{localStorage.setItem(ADMKEY,JSON.stringify({leads:DATA.leads,lab:DATA.lab,tickets:DATA.tickets,holidays:DATA.holidays,tasks:DATA.tasks,content:DATA.content,users:DATA.users,vacancies:DATA.vacancies,cms:DATA.cms,catalog:DATA.catalog,log:LOG,uType:state.uType}));}catch(e){}}
function loadData(){try{var s=JSON.parse(localStorage.getItem(ADMKEY)); if(s&&s.leads){DATA.leads=s.leads;DATA.lab=s.lab;DATA.tickets=s.tickets;DATA.holidays=s.holidays; if(s.tasks)DATA.tasks=s.tasks; if(s.content)DATA.content=s.content; if(s.users)DATA.users=s.users; if(s.vacancies)DATA.vacancies=s.vacancies; if(s.cms)DATA.cms=Object.assign({},DATA.cms,s.cms); if(s.catalog)DATA.catalog=s.catalog; if(s.log)LOG=s.log; if(s.uType)state.uType=s.uType;}}catch(e){}}
function resetData(){DATA.leads=JSON.parse(JSON.stringify(DEFAULTS.leads));DATA.lab=JSON.parse(JSON.stringify(DEFAULTS.lab));DATA.tickets=JSON.parse(JSON.stringify(DEFAULTS.tickets));DATA.holidays=JSON.parse(JSON.stringify(DEFAULTS.holidays));DATA.tasks=JSON.parse(JSON.stringify(DEFAULTS.tasks));DATA.content=JSON.parse(JSON.stringify(DEFAULTS.content||{}));DATA.users=JSON.parse(JSON.stringify(DEFAULTS.users));DATA.vacancies=JSON.parse(JSON.stringify(DEFAULTS.vacancies||[]));DATA.cms=JSON.parse(JSON.stringify(DEFAULTS.cms||{}));DATA.catalog=JSON.parse(JSON.stringify(DEFAULTS.catalog||[]));LOG=[{t:'07.06 09:14',who:'Система',msg:'Демо-данные сброшены'}];saveData();}
